      backup_text =
        "#HazelHtml Todo List Example: tonight's planting list#\n\
         #A todo list with add/remove, entered through a Form with OnSubmit#\n\
         #msg = Msg sum type, model = (todos=[String], input_value=String)#\n\n\
         type Msg =\n\
        \  + AddTodo\n\
        \  + RemoveTodo(Int)\n\
        \  + UpdateInput(String)\n\
         in\n\n\
         let init = (todos=[\"Water the moonmelons\", \"Sow starfruit \
         seeds\"], input_value=\"\") in\n\n\
         let remove_at(xs: [String], idx: Int) : [String] =\n\
        \    let indexed = mapi(xs, fun (i, x) -> (i, x)) in\n\
        \    let filtered = filter(indexed, fun pair -> fst(pair) != idx) in\n\
        \    map(filtered, fun pair -> snd(pair))\n\
         in\n\n\
         let update(msg, model) =\n\
        \  case msg\n\
        \  | AddTodo =>\n\
        \      if model.input_value == \"\" then (model, CmdNone)\n\
        \      else ((todos=model.todos @ [model.input_value], \
         input_value=\"\"), CmdNone)\n\
        \  | RemoveTodo(idx) =>\n\
        \      ((todos=remove_at(model.todos, idx), \
         input_value=model.input_value), CmdNone)\n\
        \  | UpdateInput(value) =>\n\
        \      ((todos=model.todos, input_value=value), CmdNone)\n\
        \  end\n\
         in\n\n\
         let view(model) =\n\
        \  Div(\n\
        \    [Class(\"todo-app\"), Style([(\"max-width\", \"400px\"), \
         (\"margin\", \"20px auto\"), (\"font-family\", \"sans-serif\")])],\n\
        \    [\n\
        \      H2([Style([(\"text-align\", \"center\")])], \
         [Text(\"\240\159\140\153 Planting List\")]),\n\
        \      #Submitting the form (Enter or the button) adds the chore#\n\
        \      Form(\n\
        \        [OnSubmit(AddTodo), Style([(\"display\", \"flex\"), \
         (\"margin-bottom\", \"20px\")])],\n\
        \        [\n\
        \          Input([\n\
        \            Type(\"text\"),\n\
        \            Value(model.input_value),\n\
        \            Placeholder(\"Add a garden chore...\"),\n\
        \            Required(true),\n\
        \            OnInput(fun value -> UpdateInput(value)),\n\
        \            Style([(\"flex\", \"1\"), (\"padding\", \"8px\"), \
         (\"font-size\", \"16px\")])\n\
        \          ]),\n\
        \          Button(\n\
        \            [\n\
        \              Type(\"submit\"),\n\
        \              Disabled(model.input_value == \"\"),\n\
        \              Style([(\"padding\", \"8px 16px\"), (\"background\", \
         \"#4CAF50\"), (\"color\", \"white\"), (\"border\", \"none\"), \
         (\"cursor\", \"pointer\")])\n\
        \            ],\n\
        \            [Text(\"Plant\")]\n\
        \          )\n\
        \        ]\n\
        \      ),\n\
        \      #Chores#\n\
        \      Ul(\n\
        \        [Style([(\"list-style\", \"none\"), (\"padding\", \"0\"), \
         (\"margin\", \"0\")])],\n\
        \        mapi(model.todos, fun (index, item) ->\n\
        \          Li(\n\
        \            [Style([(\"padding\", \"8px\"), (\"border-bottom\", \"1px \
         solid #eee\"), (\"display\", \"flex\"), (\"justify-content\", \
         \"space-between\")])],\n\
        \            [\n\
        \              Span([], [Text(item)]),\n\
        \              Button(\n\
        \                [\n\
        \                  OnClick(RemoveTodo(index)),\n\
        \                  Style([(\"background\", \"#ff4444\"), (\"color\", \
         \"white\"), (\"border\", \"none\"), (\"padding\", \"4px 8px\"), \
         (\"cursor\", \"pointer\")])\n\
        \                ],\n\
        \                [Text(\"X\")]\n\
        \              )\n\
        \            ]\n\
        \          )\n\
        \        )\n\
        \      ),\n\
        \      #Chore count#\n\
        \      Div(\n\
        \        [Style([(\"text-align\", \"center\"), (\"color\", \"#666\"), \
         (\"margin-top\", \"10px\")])],\n\
        \        [Text(string_of_int(length(model.todos)) ++ \" chores \
         tonight\")]\n\
        \      )\n\
        \    ]\n\
        \  )\n\
         in\n\n\
         let subs(_model) = SubNone in\n\n\
         # Tests #\n\n\
         hint \"submitting the form appends the chore\"\n\
         test\n\
        \  let (m, _cmd) = update(AddTodo, (todos=[\"A\"], input_value=\"B\")) \
         in\n\
        \  m.todos == [\"A\", \"B\"] && m.input_value == \"\"\n\
         end;\n\n\
         hint \"submitting an empty input does nothing\"\n\
         test\n\
        \  let (m, _cmd) = update(AddTodo, (todos=[\"A\"], input_value=\"\")) in\n\
        \  m.todos == [\"A\"]\n\
         end;\n\n\
         hint \"remove first todo\"\n\
         test\n\
        \  let (m, _cmd) = update(RemoveTodo(0), (todos=[\"A\", \"B\", \"C\"], \
         input_value=\"\")) in\n\
        \  m.todos == [\"B\", \"C\"]\n\
         end;\n\n\
         hint \"remove last todo\"\n\
         test\n\
        \  let (m, _cmd) = update(RemoveTodo(2), (todos=[\"A\", \"B\", \"C\"], \
         input_value=\"\")) in\n\
        \  m.todos == [\"A\", \"B\"]\n\
         end;\n\n\
         hint \"remove middle todo\"\n\
         test\n\
        \  let (m, _cmd) = update(RemoveTodo(1), (todos=[\"A\", \"B\", \"C\"], \
         input_value=\"\")) in\n\
        \  m.todos == [\"A\", \"C\"]\n\
         end;\n\n\
         hint \"update input\"\n\
         test\n\
        \  let (m, _cmd) = update(UpdateInput(\"hello\"), init) in\n\
        \  m.input_value == \"hello\"\n\
         end;\n\n\
         (init, update, view, subs)\n";
      refractors = "()";
    } )
